    );

    // Register Workflow
    worker.registerWorkflowImplementationTypes(OrderProcessingWorkflowImpl.class);

    // Start the worker
    factory.start();

    System.out.println("Temporal worker started on task queue: order-processing-task-queue");
  }
}"}

